import re

from taf.ul.sc import perf
from moler.config import devices as devices_config  # type: ignore
from moler.device import DeviceFactory  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from ta_moler.device.fzm_console import FzmConsole  # type: ignore
from ta_moler.device.air_scale import AirScale  # type: ignore
from ta_moler.device.rtg import RTG  # type: ignore


def is_fzmconsole_device(device_name):
    return _is_instance_of_device(device_name, FzmConsole)


def is_airscale_device(device_name):
    return _is_instance_of_device(device_name, AirScale)


def is_rtg_device(device_name):
    return _is_instance_of_device(device_name, RTG)


def _is_instance_of_device(device_name, inst):
    device = DeviceFactory.get_device(name=device_name, establish_connection=False)
    return isinstance(device, inst)


def is_enb(device_name):
    return re.search(r'^ENB\d+$', device_name)


def is_gnb(device_name):
    return re.search(r'^GNB\d+$', device_name)


def is_bts(device_name):
    if is_enb(device_name) or is_gnb(device_name):
        return True
    return False


def is_main_bts(bts_name):
    main_bts_regex = r"[A-Z]1$"

    if re.search(main_bts_regex, bts_name):
        return True

    return False


def get_device_number(device_name):
    match = re.search(r"^[^\W_\d]+(?P<DEVICE_NUMBER>\d+)", device_name)
    return int(match.group('DEVICE_NUMBER')) if match else False


def get_main_bts_name():
    bts_device = get_devices_from_regex(pattern='(ENB|GNB)1$')
    return bts_device[0] if bts_device else None


def get_all_enbs():
    return get_devices_from_regex(pattern=r'^(ENB\d+)$')


def get_all_small_cell_enbs():
    small_cell_enbs = []
    for enb_name in get_all_enbs():
        if is_fzmconsole_device(enb_name):
            small_cell_enbs.append(enb_name)

    return small_cell_enbs


def get_ue_sim_name():
    ue_sim_device = get_devices_from_regex(pattern=r'^(RTG|IPHY)$')
    return ue_sim_device[0] if ue_sim_device else None


def is_ue(device_name):
    return re.search(r'^(RTG|IPHY)$', device_name)


def get_devices_from_regex(pattern, reverse=False):
    devices = []
    compiled_pattern = re.compile(pattern)
    for device_name in devices_config.named_devices:
        if compiled_pattern.search(device_name):
            devices.append(device_name)

    devices.sort(key=lambda name: get_device_number(name), reverse=reverse)

    return devices


def get_test_line_location(test_line_name=None):
    if test_line_name is None:
        test_line_name = perf.tl.name
    site_codes = {
        '1': 'Arlington Heights',
        '2': 'Bangalore',
        '3': 'Beijing',
        '4': 'Espoo',
        '5': 'Hangzhou',
        '6': 'Irving',
        '7': 'Krakow',
        '8': 'Manila',
        '9': 'Murray Hills',
        '10': 'Naperville',
        '11': 'Oulu',
        '12': 'Shanghai',
        '13': 'Tokio',
        '14': 'Tampere',
        '15': 'Ulm',
        '16': 'Wroclaw',
        '17': 'Lannion',
        '18': 'Timisoara',
        '19': 'Kawasaki',
        '20': 'Paris-Saclay',
        '21': 'Nanjing',
    }

    lab_location = None
    match = re.search(r"^(?P<ORGANIZATION_CODE>\d+)_(?P<SITE_CODE>\d+)", test_line_name)
    if match:
        lab_location_code = match.group('SITE_CODE')
        if lab_location_code in site_codes:
            lab_location = site_codes[lab_location_code]
        else:
            msg = "Site Code: {} not supported. Available codes"
            MolerTest.error(msg=msg, dump=site_codes)

    return lab_location


def get_dsp_device_name(device_name):
    return device_name.replace('_WS', '') + "_DSP"
